refsyn.codeblock:
value   = token { whitespace token }
token   = version                 (* exact: that version and everything under it *)
        | version ".."            (* from: that version and later *)
        | ".." version            (* to: up to and including everything under it *)
        | version ".." version    (* from .. to *)
version = [ "v" | "V" ] digits { "." digits }
digits  = "0" .. "9" { "0" .. "9" }
